import sys; sys.path.insert(0,"/app")
import numpy as np, time
import forward
D=10; H=1e-5
def grad(x):
    g=np.empty(D)
    for j in range(D):
        e=np.zeros(D); e[j]=H
        g[j]=(forward.forward(x+e)-forward.forward(x-e))/(2*H)
    return g
def line_jumps(x0,d,T=20.0,eps=1e-3,gtol=1e-8,n_init=2000):
    ts=np.linspace(-T,T,n_init); gs=[grad(x0+t*d) for t in ts]; out=[]
    stack=[(ts[k],ts[k+1],gs[k],gs[k+1]) for k in range(n_init-1)]
    while stack:
        lo,hi,gl,gh=stack.pop()
        if np.linalg.norm(gh-gl)<=gtol: continue
        if hi-lo<=eps: out.append(gh-gl); continue
        mid=0.5*(lo+hi); gm=grad(x0+mid*d)
        stack.append((lo,mid,gl,gm)); stack.append((mid,hi,gm,gh))
    return out
def run(seed,NL=6,**kw):
    rng=np.random.default_rng(seed); allj=[]; per=[]
    for _ in range(NL):
        x0=rng.standard_normal(D); d=rng.standard_normal(D); d/=np.linalg.norm(d)
        js=line_jumps(x0,d,**kw); per.append(len(js)); allj+=js
    V=np.array(allj); N=V/np.linalg.norm(V,axis=1,keepdims=True)
    for i in range(len(N)):
        k=np.argmax(np.abs(N[i]))
        if N[i,k]<0: N[i]*=-1
    clusters=[]
    for v in N:
        for c in clusters:
            if c['mean']@v>0.9999:
                c['members'].append(v); c['mean']=np.mean(c['members'],axis=0); c['mean']/=np.linalg.norm(c['mean']); break
        else: clusters.append({'mean':v.copy(),'members':[v]})
    clusters=[c for c in clusters if len(c['members'])>=3]
    U=np.array([c['mean'] for c in clusters])
    A1=forward.A1; tn=A1/np.linalg.norm(A1,axis=1,keepdims=True)
    prec=np.abs(tn@U.T); used=set(); cos=[]
    for i in range(len(tn)):
        for j in np.argsort(-prec[i]):
            if j not in used: used.add(j); cos.append(prec[i,j]); break
    return per,len(allj),len(U),min(cos) if cos else -1
t0=time.time()
for seed in range(10):
    print(seed, run(seed))
print('elapsed',time.time()-t0)
