import sys; sys.path.insert(0,"/app")
import numpy as np, time
import forward
exec(open('/tmp/sign_test.py').read().split("U,beta,cl=extract(0)")[0])
def recover(seed, rng_reg=123):
    U,beta,cl=extract(seed)
    A1=forward.A1; tn=A1/np.linalg.norm(A1,axis=1,keepdims=True)
    prec=np.abs(tn@U.T); used=set(); match={}
    for i in range(20):
        for j in np.argsort(-prec[i]):
            if j not in used: used.add(j); match[i]=j; break
    rng=np.random.default_rng(rng_reg)
    n=len(U); M=max(400,20*n)
    sscale=max(1.0, 3*np.median(np.abs(beta))*1.5)
    X=rng.standard_normal((M,D))*sscale
    y=np.array([forward.forward(x) for x in X])
    Z=X@U.T+beta
    def fit(sig):
        F=np.maximum(0,Z*sig); A=np.hstack([F,np.ones((M,1))])
        coef,_,_,_=np.linalg.lstsq(A,y,rcond=None)
        return np.linalg.norm(A@coef-y)
    inv={j:i for i,j in match.items()}
    sig_true=np.array([1.0 if A1[inv[j]]@U[j]>0 else -1.0 for j in range(n)])
    rt=fit(sig_true)
    best=(1e18,None)
    for restart in range(30):
        sig=rng.choice([-1.0,1.0],size=n); r=fit(sig)
        for it in range(15):
            improved=False
            for i in rng.permutation(n):
                s2=sig.copy(); s2[i]*=-1; r2=fit(s2)
                if r2<r-1e-12: sig=s2; r=r2; improved=True
            if not improved: break
        if r<best[0]: best=(r,sig.copy())
    mis=int(np.sum(best[1]!=sig_true)) if best[1] is not None else -1
    return n,round(rt,3),round(best[0],6),mis,round(sscale,2)
t0=time.time()
for s in range(10):
    print('extract seed',s,recover(s))
print('elapsed',time.time()-t0)
